#!/usr/bin/env python3
"""Verification gate (generated by secant). Runs when the agent says it's done (a Stop hook), or by hand:

    python .secant/verify.py            # human-readable report
    python .secant/verify.py --hook     # hook mode: prints a block decision when something needs attention

It checks the change against this repository's own evidence, not against any hidden test:
1. tests that exercise the changed functions (coverage map) plus the tests the agent added or changed;
   failures that already happen without the change are ignored;
2. the repo's existing expected outputs for the constructs involved (tests' canonical forms);
3. a behavior diff: how outputs for the issue's SQL and related test inputs changed, dialect by dialect.
"""

import ast
import json
import os
import random
import subprocess
import sys
import tempfile
from pathlib import Path

HERE = Path(os.environ.get("SECANT_TOOL_DIR") or Path(__file__).resolve().parent)
REPO = Path.cwd()
BUDGET_S = int(os.environ.get("SECANT_VERIFY_BUDGET", "150"))
MAX_BLOCKS = 3
STATE = Path(tempfile.gettempdir()) / "secant-verify-blocks"


def sh(*args, cwd=None, env=None, timeout=60):
    r = subprocess.run(args, cwd=cwd or REPO, capture_output=True, text=True, env=env, timeout=timeout)
    return r.stdout


def cfg():
    return json.loads((HERE / "verify.json").read_text())


def root_commit():
    return sh("git", "rev-list", "--max-parents=0", "HEAD").split()[-1]


def changed(root, prefixes):
    tracked = sh("git", "diff", "--name-only", root).split()
    untracked = sh("git", "ls-files", "--others", "--exclude-standard").split()
    return sorted({p for p in tracked + untracked if p.endswith(".py") and p.startswith(tuple(prefixes))})


def def_ranges(src):
    out = []
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return out

    def walk(node, prefix):
        for c in ast.iter_child_nodes(node):
            if isinstance(c, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                q = f"{prefix}.{c.name}" if prefix else c.name
                out.append((c.lineno, c.end_lineno or c.lineno, q))
                walk(c, q)
            else:
                walk(c, prefix)

    walk(tree, "")
    return out


def enclosing(ranges, line):
    best, size = "<module>", None
    for s, e, q in ranges:
        if s <= line <= e and (size is None or e - s < size):
            best, size = q, e - s
    return best


def touched_functions(root, files):
    out = set()
    for f in files:
        diff = sh("git", "diff", "-U0", root, "--", f)
        p = REPO / f
        new_ranges = def_ranges(p.read_text(errors="replace")) if p.exists() else []
        old_src = sh("git", "show", f"{root}:{f}")
        old_ranges = def_ranges(old_src) if old_src else []
        if not diff and p.exists():  # untracked new file
            out.add(f"{f}::<module>")
            continue
        for line in diff.splitlines():
            if line.startswith("@@"):
                old, new = line.split()[1:3]
                o = int(old[1:].split(",")[0])
                n = int(new[1:].split(",")[0])
                out.add(f"{f}::{enclosing(new_ranges, max(n, 1))}")
                if old_ranges:
                    out.add(f"{f}::{enclosing(old_ranges, max(o, 1))}")
    return out


def impacted_tests(touched, own_tests):
    cov_path = HERE / "coverage.json"
    cov = json.loads(cov_path.read_text()) if cov_path.exists() else {}
    hits = {}
    for ft in touched:
        f, _, q = ft.partition("::")
        fns = cov.get(f, {})
        tests = fns.get(q)
        if tests is None:
            tests = sorted({t for ts in fns.values() for t in ts})
        for t in tests:
            hits[t] = hits.get(t, 0) + 1
    ordered = sorted(hits, key=lambda t: (-hits[t], t))
    return list(own_tests) + [t for t in ordered if t.split("::")[0] not in own_tests]


def run_pytest(targets, pythonpath, cwd, budget):
    if not targets:
        return {}, False
    with tempfile.TemporaryDirectory() as d:
        xml = Path(d) / "j.xml"
        env = {**os.environ, "PYTHONPATH": str(pythonpath), "PYTHONDONTWRITEBYTECODE": "1"}  # no stale .pyc between checks
        try:
            subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", "-o", "junit_family=xunit2",
                            f"--junitxml={xml}", *targets], cwd=cwd, env=env, capture_output=True, timeout=budget)
            timed_out = False
        except subprocess.TimeoutExpired:
            timed_out = True
        if not xml.exists():
            return {}, timed_out
        import xml.etree.ElementTree as ET
        res = {}
        for case in ET.parse(xml).getroot().iter("testcase"):
            tid = f"{case.get('classname')}::{case.get('name')}"
            bad = next((c for c in case if c.tag in ("failure", "error")), None)
            res[tid] = ("fail", ((bad.get("message") or "") + " " + (bad.text or ""))[:400]) if bad is not None else ("pass", "")
        return res, timed_out


def base_worktree(root):
    wt = Path(tempfile.gettempdir()) / "secant-verify-base"
    if not (wt / ".git").exists():
        subprocess.run(["git", "worktree", "add", "--detach", "-f", str(wt), root], cwd=REPO, capture_output=True)
        prep = HERE / "prepare.sh"
        if prep.exists():
            subprocess.run(["bash", str(prep)], cwd=wt, capture_output=True)
    return wt


BEHAVE = r"""
import json, sys
src = open(sys.argv[1]).read()
ns = {}
exec(src, ns)
out = []
for s in json.load(sys.stdin):
    out.append(ns["behave"](s["input"], s["read"], s["write"]))
print(json.dumps(out))
"""


def behave(samples, pythonpath, cwd):
    if not samples:
        return []
    env = {**os.environ, "PYTHONPATH": str(pythonpath), "PYTHONDONTWRITEBYTECODE": "1"}  # no stale .pyc between checks
    r = subprocess.run([sys.executable, "-c", BEHAVE, str(HERE / "behavior.py")], input=json.dumps(samples),
                       cwd=cwd, env=env, capture_output=True, text=True, timeout=120)
    try:
        return json.loads(r.stdout)
    except json.JSONDecodeError:
        return ["!behavior failed: " + r.stderr[-200:]] * len(samples)


def samples_for(impacted_ids, c):
    rows = json.loads((HERE / "tests.json").read_text()) if (HERE / "tests.json").exists() else []
    impacted_names = {t.split("::", 1)[-1] for t in impacted_ids}
    exp = [r for r in rows if r["test"] in impacted_names]
    random.Random(0).shuffle(exp)
    issue = [{"input": s, "read": d, "write": w, "expected": None, "where": "issue"}
             for s in c.get("issue_sql", [])[:6] for d in (c.get("issue_dialects") or [""])[:3]
             for w in (c.get("issue_dialects") or [""])[:4]]
    tests = [{"input": r["input"], "read": r["read"], "write": r["write"], "expected": r["expected"],
              "where": f"{r['file']}:{r['line']}"} for r in exp[:150]]
    return issue + tests


def main(hook):
    c = cfg()
    if hook:
        try:
            payload = json.loads(sys.stdin.read() or "{}")
        except json.JSONDecodeError:
            payload = {}
        blocks = int(STATE.read_text()) if STATE.exists() else 0
        if blocks >= MAX_BLOCKS:
            return 0
    root = root_commit()
    src_changed = changed(root, c["src_prefixes"])
    test_changed = changed(root, c["test_prefixes"])
    report, block = [], False
    new_failures, violations, changes = {}, [], []
    if not src_changed:
        report.append("No source file has changed yet. The task needs a change to the code under "
                      + ", ".join(c["src_prefixes"]) + " (test-only changes don't fix it).")
        block = True
    else:
        touched = touched_functions(root, src_changed)
        tests = impacted_tests(touched, test_changed)
        files = list(dict.fromkeys(t.split("::")[0] for t in tests))[:25]
        head, timed_out = run_pytest(files, REPO, REPO, BUDGET_S)
        failing = {t: m for t, (s, m) in head.items() if s == "fail"}
        if failing:
            wt = base_worktree(root)
            base, _ = run_pytest(files, wt, wt, BUDGET_S)
            new_failures = {t: m for t, m in failing.items() if base.get(t, ("fail", ""))[0] == "pass"}
        samples = samples_for(tests, c)
        wt = base_worktree(root)
        before = behave(samples, wt, wt)
        after = behave(samples, REPO, REPO)
        # Expected outputs that held before the change and don't now (pre-existing mismatches are ignored).
        violations = [(s, a) for s, b, a in zip(samples, before, after)
                      if s["expected"] is not None and b == s["expected"] and a != s["expected"]]
        changes = [(s, b, a) for s, b, a in zip(samples, before, after) if b != a]
        report.append(f"Checked {len(src_changed)} changed source file(s), {len(touched)} changed function(s); ran "
                      f"{len(head)} tests from {len(files)} file(s){' (time budget hit)' if timed_out else ''}.")
        if new_failures:
            block = True
            report.append(f"{len(new_failures)} test(s) now fail that passed before your change:")
            report += [f"  - {t}: {m.strip()[:220]}" for t, m in list(new_failures.items())[:12]]
        if violations:
            block = True
            report.append(f"{len(violations)} existing expected output(s) in this repo's tests no longer hold:")
            report += [f"  - [{s['read'] or 'default'} -> {s['write'] or 'default'}] {s['input'][:120]}\n"
                       f"      expected: {s['expected'][:160]}\n      now:      {str(a)[:160]}   ({s['where']})"
                       for s, a in violations[:10]]
        if changes:
            report.append(f"Your change altered {len(changes)} output(s) (before -> after). Check each is intended "
                          "and matches how the repo writes the same construct elsewhere:")
            report += [f"  - [{s['read'] or 'default'} -> {s['write'] or 'default'}] {s['input'][:110]}\n"
                       f"      before: {str(b)[:150]}\n      after:  {str(a)[:150]}" for s, b, a in changes[:12]]
            if hook and (int(STATE.read_text()) if STATE.exists() else 0) == 0:
                block = True  # show the behavior diff once, so the agent reviews the consequences
    text = "\n".join(report)
    if "--json" in sys.argv:
        print(json.dumps({"block": block, "src_changed": bool(src_changed), "new_failures": len(new_failures),
                          "violations": len(violations), "changes": len(changes), "report": text}))
        return 0
    if hook:
        if block:
            STATE.write_text(str((int(STATE.read_text()) if STATE.exists() else 0) + 1))
            print(json.dumps({"decision": "block", "reason": "secant verification:\n" + text[:6000]}))
        return 0
    print(text)
    return 0


if __name__ == "__main__":
    sys.exit(main("--hook" in sys.argv))
